tool_call_arguments:
{"command": "cd /work/analysis && python3 << 'EOF'
import docx
d = docx.Document('/work/output/Meridian_Strategic_Investment_Memo.docx')
words = 0
for p in d.paragraphs:
    words += len(p.text.split())
tbl_words = 0
for t in d.tables:
    for row in t.rows:
        for c in row.cells:
            tbl_words += len(c.text.split())
print('Paragraph words:', words, '| table words:', tbl_words, '| tables:', len(d.tables))
print('Paragraph count:', len(d.paragraphs))
# rough page estimate: ~550-650 words/page at 10.5pt with tables
print('Estimated pages:', round((words+tbl_words)/550, 1))
print('--- Headings ---')
for p in d.paragraphs:
    t = p.text.strip()
    if t and (t[0].isdigit() and '.' in t[:3] or t.startswith('MERIDIAN') or t.startswith('STRATEGIC')):
        print(' ', t[:80])
EOF", "description": "Validate memo docx content"}

